using UnityEngine;using System.Collections;using System.Reflection;using System.IO;using System.Linq;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
namespace IntegratedCampaign {
public sealed class CampaignDeliveryVerification:MonoBehaviour {
 string log="";void Check(bool pass,string text){log+=(pass?"PASS ":"FAIL ")+text+"\n";File.WriteAllText("Tools/CampaignIntegration/delivery-verification.txt",log);if(!pass)throw new System.Exception(text);}
 IEnumerator Start(){DontDestroyOnLoad(gameObject);var f=CampaignFlow.Instance;f.Go(CampaignPhase.IntroVoyage);yield return Wait();var d=FindFirstObjectByType<ShipCampaignDirector>();d.Dialogue.Clear();yield return null;var ship=d.GetComponent<ShipController>();var start=ship.transform.position;InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(Key.D));yield return new WaitForSecondsRealtime(.6f);InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());yield return null;Check(ship.transform.position.x>start.x+.1f,"native D movement unlocks after dialogue");
 var hud=FindFirstObjectByType<ShipHUDController>();var manager=FindFirstObjectByType<ShipUIManager>();Check(hud.ship==ship&&hud.health==ship.GetComponent<PlayerHealth>()&&hud.upgradeProgress==manager,"HUD bound to native ship stats");ship.currentEnergy=ship.maxEnergy*.37f;yield return null;yield return null;Check(Mathf.Abs(hud.energyFill.fillAmount-.37f)<.02f,"HUD energy tracks actual ship energy");
 var toggle=hud.GetComponentInChildren<OrbRewardToggleView>();var rect=(RectTransform)toggle.transform;var click=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current);click.button=UnityEngine.EventSystems.PointerEventData.InputButton.Left;click.position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(new Vector3(rect.rect.xMin+20,0,0)));toggle.OnPointerClick(click);Check(!manager.isLootingXP,"HUD pointer selects native energy rewards");var lootPrefab=d.smallFish[0].GetComponent<Enemy>().lootPrefab;float energyBefore=ship.currentEnergy;Instantiate(lootPrefab,ship.transform.position,Quaternion.identity);yield return new WaitForSecondsRealtime(.3f);Check(ship.currentEnergy>energyBefore&&manager.currentXP==0,"native loot restores selected energy only");InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(Key.Space));yield return null;yield return null;InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());Check(manager.isLootingXP,"Space selects native XP rewards");Instantiate(lootPrefab,ship.transform.position,Quaternion.identity);yield return new WaitForSecondsRealtime(.3f);Check(manager.currentXP>0&&hud.xpFill.fillAmount>0,"native loot and HUD share upgrade XP");ship.GetComponent<PlayerHealth>().TakeDamage(10);yield return null;yield return null;Check(hud.healthFill.fillAmount<1,"HUD health reacts to damage");ship.GetComponent<PlayerHealth>().SetMaxHealth(ship.GetComponent<PlayerHealth>().maxHealth,true);ship.AddEnergy(100);

 d.GetComponent<Rigidbody2D>().position=new Vector2(-10,0);InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(Key.D));yield return new WaitForSecondsRealtime(.6f);InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());yield return null;Check(d.Tank>0,"native cruising fills tank inside collection area");
 d.GetType().GetProperty("Tank").GetSetMethod(true).Invoke(d,new object[]{1f});d.GetComponent<Rigidbody2D>().position=d.dockPoint;yield return null;d.Dialogue.Clear();InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(Key.E));yield return null;yield return null;InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());Check(d.Delivered,"E interaction starts delivery at harbor");Check(!f.CompleteDelivery(FindFirstObjectByType<ShipUIManager>(),d.GetComponent<PlayerExperience>()),"same delivery cannot reward twice");bool rewardSeen=false;for(int i=0;i<600&&!f.Transitioning;i++){if(d.Dialogue.Active)d.Dialogue.Advance();var ui=FindFirstObjectByType<ShipUIManager>();if(ui.levelUpOverlay&&ui.levelUpOverlay.activeSelf){rewardSeen=true;ui.OnCardClicked(0);}yield return null;}
 yield return Wait();Check(rewardSeen&&f.Upgrades.Count>0,"delivery reward opens existing upgrade cards");Check(f.Phase==CampaignPhase.Announcement,"delivery triggers day 2 underwater");int owned=f.Upgrades.Count;f.Go(CampaignPhase.SmallFishBattle);yield return Wait();Check(f.Upgrades.Count==owned,"owned upgrades survive scene changes");d=FindFirstObjectByType<ShipCampaignDirector>();d.Dialogue.Clear();yield return null;d.GetComponent<PlayerHealth>().TakeDamage(99999);yield return Wait();Check(f.Phase==CampaignPhase.SmallFishBattle&&f.Upgrades.Count==owned,"actual ship death retries same expedition with upgrades");Check(FindFirstObjectByType<ShipCampaignDirector>().Tank==0,"retry resets tank");Check(FindFirstObjectByType<PlayerHealth>().CurrentHealth>0,"retry restores health");f.ReturnMenu();yield return Wait();Check(FindObjectsByType<CampaignFlow>(FindObjectsSortMode.None).Length==1,"one flow after death and menu");}
 IEnumerator Wait(){yield return new WaitForSecondsRealtime(2);while(CampaignFlow.Instance.Transitioning)yield return null;yield return new WaitForSecondsRealtime(.5f);}
}
}
